style:
/* Base link styling */
.custom-booking-link {
    height: 80px; /* Equivalent to h-20 */
    border-color: var(--border-color, #e2e8f0) !important; /* Matches Frappe's native border */
    transition: all 0.2s ease-in-out;
}

/* Simulated custom border ring around the image */
.ring-border {
    box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.05), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
}

/* Precise Text colors matching your screenshot */
.booking-title {
    color: #006672 !important; /* Teal-blue primary from image */
    font-size: 1.125rem; /* text-lg */
    line-height: 1.25;
    letter-spacing: -0.025em;
}

.booking-subtitle {
    color: #007f8c !important; /* Slightly distinct or standard desk color */
}

/* Hover effects matching Tailwind's group-hover:scale-105 */
.custom-booking-link:hover .logo-container,
.custom-booking-link:hover .text-container {
    transform: scale(1.05);
}

.logo-container, .text-container {
    transition: transform 0.2s ease-in-out;
}

/* Frappe Dark Mode overrides */
[data-theme="dark"] .custom-booking-link {
    border-color: var(--dark-border-color, #2d3748) !important;
}
[data-theme="dark"] .logo-container {
    background-color: #1a202c !important;
    box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.1);
}
